contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(deposit >= 0);
        require(address(this).balance >= deposit);

        address recipient = address(this);

        c.getFirstWithdrawalBonus(recipient); if (__ESBMC_reverted()) return;

        uint balanceBefore = address(c).balance;
        bool reverted;
        c.withdrawReward(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && balanceBefore - address(c).balance == 0);
    }

    receive() external payable {}
}

