pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(uint256 deposit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(deposit >= 0);
        vm.assume(address(this).balance >= deposit);
        address recipient = address(this);
        try c.getFirstWithdrawalBonus(recipient) {} catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdrawReward(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && balanceBefore - address(c).balance == 0);
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
